		iifname "ens160" jump nat_PRE_public
		iifname "ens160" return
		jump nat_PRE_policy_allow-host-ipv6
		jump nat_PRE_public
		return
	}

	chain nat_POSTROUTING {
		type nat hook postrouting priority srcnat + 10; policy accept;
		jump nat_POSTROUTING_POLICIES
	}

	chain nat_POSTROUTING_POLICIES {
		iifname "ens160" oifname "ens160" jump nat_POST_public
		iifname "ens160" oifname "ens160" return
		oifname "ens160" jump nat_POST_public
		oifname "ens160" return
		iifname "ens160" jump nat_POST_public
		iifname "ens160" return
		jump nat_POST_public
		return
	}

	chain nat_OUTPUT {
		type nat hook output priority dstnat + 10; policy accept;
		jump nat_OUTPUT_POLICIES
	}

	chain nat_OUTPUT_POLICIES {
		oifname "ens160" jump nat_OUT_public
